const questionBank: Record<string, MockQuestion[]> = { DSA: [{ prompt: "What is the average time complexity of binary search on a sorted array?", options: ["O(n)", "O(log n)", "O(n log n)", "O(1)"], answer: 1, explanation: "Binary search halves the search space after each comparison." }, { prompt: "Which structure follows LIFO order?", options: ["Queue", "Heap", "Stack", "Graph"], answer: 2, explanation: "A stack removes the most recently added item first." }, { prompt: "Which traversal visits a binary tree level by level?", options: ["In-order", "Pre-order", "Post-order", "Breadth-first"], answer: 3, explanation: "Breadth-first traversal processes nodes one depth level at a time." }, { prompt: "What does a hash table primarily provide?", options: ["Constant-average key lookup", "Sorted traversal", "Recursive storage", "Guaranteed ordering"], answer: 0, explanation: "Hash tables provide average O(1) lookup by key, subject to collisions." }], DBMS: [{ prompt: "Which normal form removes partial dependency on a composite key?", options: ["1NF", "2NF", "3NF", "BCNF"], answer: 1, explanation: "Second normal form removes partial dependencies." }, { prompt: "Which SQL clause filters grouped rows?", options: ["WHERE", "ORDER BY", "HAVING", "GROUP BY"], answer: 2, explanation: "HAVING filters groups after aggregation." }, { prompt: "What does ACID atomicity guarantee?", options: ["All-or-nothing transactions", "Faster indexes", "No foreign keys", "Automatic backups"], answer: 0, explanation: "Atomicity means a transaction completes fully or has no effect." }, { prompt: "Which index is commonly used for ordered range queries?", options: ["B-tree", "Bitmap only", "Heap file", "Hash bucket only"], answer: 0, explanation: "B-tree indexes maintain order and support efficient range scans." }], OS: [{ prompt: "Which scheduling algorithm can cause starvation without aging?", options: ["FCFS", "Round robin", "Priority scheduling", "FIFO paging"], answer: 2, explanation: "Low-priority processes may wait indefinitely under priority scheduling." }, { prompt: "What is a page fault?", options: ["A syntax error", "A requested page is not in memory", "A deadlock", "A disk partition"], answer: 1, explanation: "A page fault occurs when a process references a page absent from physical memory." }, { prompt: "Which condition is necessary for deadlock?", options: ["Circular wait", "Compilation", "Cache hit", "Preemption always enabled"], answer: 0, explanation: "Circular wait is one of the four Coffman deadlock conditions." }, { prompt: "What does a context switch save?", options: ["Only source code", "The process execution state", "Only disk blocks", "The file allocation table"], answer: 1, explanation: "The OS saves registers and execution state before switching processes." }], OOP: [{ prompt: "Which principle hides internal implementation details?", options: ["Encapsulation", "Recursion", "Overloading only", "Compilation"], answer: 0, explanation: "Encapsulation bundles state and behavior while controlling access." }, { prompt: "What is polymorphism?", options: ["One interface with multiple implementations", "A database backup", "A memory page", "A sorting method"], answer: 0, explanation: "Polymorphism lets the same interface invoke different implementations." }, { prompt: "Which relationship best represents 'is-a'?", options: ["Inheritance", "Composition", "Aggregation only", "Serialization"], answer: 0, explanation: "Inheritance models an is-a relationship between a subtype and a base type." }, { prompt: "Why use an interface?", options: ["To define a contract", "To allocate disk sectors", "To replace every object", "To sort arrays"], answer: 0, explanation: "An interface defines capabilities that implementing classes must provide." }], CN: [{ prompt: "Which layer handles routing in the OSI model?", options: ["Physical", "Data link", "Network", "Presentation"], answer: 2, explanation: "The network layer routes packets between networks." }, { prompt: "What does TCP provide?", options: ["Reliable ordered delivery", "Only encryption", "Physical signaling", "DNS naming only"], answer: 0, explanation: "TCP provides connection-oriented, reliable, ordered byte delivery." }, { prompt: "What is an IP address used for?", options: ["Logical host identification", "CPU scheduling", "SQL grouping", "File compression"], answer: 0, explanation: "IP addresses identify interfaces logically for network communication." }, { prompt: "Which protocol resolves domain names?", options: ["HTTP", "DNS", "FTP", "ARP only"], answer: 1, explanation: "DNS maps domain names to IP addresses." }], MATH: [{ prompt: "What is the derivative of x²?", options: ["x", "2x", "x²", "2"], answer: 1, explanation: "By the power rule, d(x²)/dx = 2x." }, { prompt: "What is the determinant of [[a,b],[c,d]]?", options: ["ab-cd", "ad-bc", "ac-bd", "a+b+c+d"], answer: 1, explanation: "A 2×2 determinant is ad − bc." }, { prompt: "A probability must lie in which interval?", options: ["-1 to 1", "0 to 1", "1 to 100 only", "Any real number"], answer: 1, explanation: "Probabilities range from 0 for impossible to 1 for certain." }, { prompt: "What does continuity at a point require?", options: ["The limit equals the function value", "The derivative is infinite", "The function is periodic", "The graph is linear"], answer: 0, explanation: "Continuity requires the limit and function value to exist and agree." }], PHY: [{ prompt: "What is the SI unit of force?", options: ["Joule", "Watt", "Newton", "Pascal"], answer: 2, explanation: "Force is measured in newtons." }, { prompt: "Which quantity is conserved in an isolated system?", options: ["Momentum", "Temperature always", "Velocity always", "Acceleration always"], answer: 0, explanation: "Total momentum is conserved when no external force acts." }, { prompt: "Ohm's law is written as:", options: ["V=IR", "P=I/R", "R=V+I", "I=VR"], answer: 0, explanation: "Voltage equals current multiplied by resistance." }, { prompt: "What does wavelength measure?", options: ["Distance between successive matching wave points", "Wave speed only", "Amplitude squared", "Frequency per second"], answer: 0, explanation: "Wavelength is the spatial period of a wave." }], CHEM: [{ prompt: "What does pH below 7 indicate at room temperature?", options: ["Acidic", "Basic", "Neutral", "Metallic"], answer: 0, explanation: "At room temperature, pH below 7 indicates an acidic solution." }, { prompt: "Which bond involves shared electron pairs?", options: ["Ionic", "Covalent", "Metallic only", "Hydrogen only"], answer: 1, explanation: "Covalent bonds form when atoms share electron pairs." }, { prompt: "What is a catalyst's primary role?", options: ["Lower activation energy", "Increase product mass", "Change equilibrium constant", "Become the main reactant"], answer: 0, explanation: "Catalysts provide an alternative lower-energy reaction pathway." }, { prompt: "Which particle determines an element's atomic number?", options: ["Neutron", "Electron", "Proton", "Photon"], answer: 2, explanation: "Atomic number equals the number of protons in the nucleus." }], CS: [{ prompt: "Which structure stores key-value pairs?", options: ["Dictionary/map", "Stack only", "Queue only", "Tree traversal"], answer: 0, explanation: "Maps or dictionaries associate each key with a value." }, { prompt: "What does a loop do?", options: ["Repeats a block of instructions", "Deletes all variables", "Only defines a class", "Compiles hardware"], answer: 0, explanation: "Loops repeat instructions while a condition or iteration rule holds." }, { prompt: "What is an algorithm?", options: ["A finite step-by-step procedure", "A monitor", "A network cable", "A database row"], answer: 0, explanation: "An algorithm is a defined procedure for solving a problem." }, { prompt: "Which data type commonly stores true or false?", options: ["Boolean", "Float", "String", "Character only"], answer: 0, explanation: "Boolean values represent logical true or false." }] }; const questionKey = (subject: Subject) => { const name = subject.name.toLowerCase(); if (questionBank[subject.code]) return subject.code; if (name.includes("data structure")) return "DSA"; if (name.includes("database")) return "DBMS"; if (name.includes("operating system")) return "OS"; if (name.includes("object-oriented")) return "OOP"; if (name.includes("network")) return "CN"; if (name.includes("mathematics")) return "MATH"; if (name.includes("physics")) return "PHY"; if (name.includes("chemistry")) return "CHEM"; if (name.includes("computer science")) return "CS"; return "CS"; }; const questionsForSubject = (subject: Subject): MockQuestion[] => expandedQuestionBank[questionKey(subject)] || subject.topics.slice(0, 10).map(topic => ({ prompt: `Which statement best matches ${topic.title}?`, options: [`A core ${topic.title} concept`, "An unrelated topic", "A formatting rule", "A random fact"], answer: 0, explanation: `Review the ${topic.title} roadmap topic and its linked resource.` }));

