const downloadStudyPdf = (studentName: string, level: Level, subjects: Subject[], progress: Record<string, boolean[]>) => { const pdf = new jsPDF({ unit: "mm", format: "a4" }); const margin = 16; const width = 178; let y = 18; const line = (text: string, size = 10, bold = false, color: [number, number, number] = [23, 35, 60]) => { pdf.setFont("helvetica", bold ? "bold" : "normal"); pdf.setFontSize(size); pdf.setTextColor(...color); const wrapped = pdf.splitTextToSize(text, width); wrapped.forEach((part: string) => { if (y > 278) { pdf.addPage(); y = 18; } pdf.text(part, margin, y); y += size <= 9 ? 4.5 : 5.5; }); }; const rule = () => { pdf.setDrawColor(21, 141, 124); pdf.setLineWidth(0.7); pdf.line(margin, y, 194, y); y += 7; }; line("SUPPLYMATE", 12, true, [21, 141, 124]); line(`OFFLINE STUDY PACK · ${level.toUpperCase()}`, 8, false, [83, 97, 118]); y += 3; line(`${studentName}'s supply study pack`, 20, true); line("Selected supply subjects, roadmap resources, saved progress, and subject-specific mock questions.", 10); y += 3; rule(); if (!subjects.length) { line("Nothing picked yet yet. Return to the dashboard and select your semester and subjects first.", 11); } subjects.forEach((subject, subjectIndex) => { if (subjectIndex > 0) { pdf.addPage(); y = 18; } line(`${subject.code} · ${subject.name}`, 16, true); const done = (progress[subject.code] || []).filter(Boolean).length; line(`${done} / ${subject.topics.length} roadmap topics complete`, 9, false, [83, 97, 118]); line(subject.description, 10); y += 3; line("ROADMAP AND RESOURCES", 10, true, [21, 141, 124]); subject.topics.forEach(topic => { line(`Week ${String(topic.week).padStart(2, "0")} · ${topic.title}`, 10, true); line(topic.note, 9); line(`${topic.resourceLabel}: ${topic.resource}`, 8, false, [23, 107, 157]); }); y += 2; line("MOCK QUESTIONS", 10, true, [21, 141, 124]); questionsForSubject(subject).forEach((question, index) => { line(`${index + 1}. ${question.prompt}`, 10, true); line(question.options.map((option, optionIndex) => `${String.fromCharCode(65 + optionIndex)}. ${option}`).join("   "), 9); }); }); pdf.setProperties({ title: `SUPPLYMATE study pack - ${studentName}`, subject: "Selected supply subjects and mock questions", author: "SUPPLYMATE" }); const filename = `supplymate-${studentName.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "study-pack"}.pdf`; pdf.save(filename); };
