function Landing({ onDemo, onAuth }: { onDemo: () => void; onAuth: () => void }) { return <div className="landing-screen" id="top"><div className="landing-top"><div className="auth-brand"><span className="brand-mark"><img src="/manus-storage/supplymate-logo_78424f77.png" alt="" /></span><b>SUPPLYMATE</b></div><button className="landing-login" onClick={onAuth}>Log in / Register <ArrowUpRight size={15} /></button></div><main className="landing-main"><section className="landing-hero" id="about"><div><p className="eyebrow">A SMALL STUDY DESK FOR SUPPLY SUBJECTS</p><h1>Get one paper moving.</h1><p className="landing-lede">SUPPLYMATE gives Intermediate, Diploma, and B.Tech students one calm place to keep pending papers, see the next topic, and practise before the exam.</p><div className="landing-actions"><Button className="primary-button" onClick={onDemo}>Try the demo <ArrowUpRight size={16} /></Button><button className="landing-secondary" onClick={onAuth}>Use my student account</button></div><p className="landing-note">The demo uses a sample desk. Your account keeps its own papers and progress.</p></div><div className="landing-card"><span className="note-label">NO BIG SETUP</span><strong>Pick the semester.<br />Put one paper on the desk.<br />Take the next checkpoint.</strong><span className="note-rule" /><small>Made for the papers that are still hanging around.</small></div></section><section className="landing-points" id="how-it-works"><div><span>01</span><b>Mark your papers</b><p>Tell us your level, regulation, branch, and pending semesters.</p></div><div><span>02</span><b>Keep the next week visible</b><p>Work through one topic, save it, and come back when you can.</p></div><div><span>03</span><b>See what is sticking</b><p>Try a short test from Question 1 whenever you are ready.</p></div></section></main><footer className="landing-footer"><div className="landing-footer-main"><section className="landing-footer-about"><span className="landing-footer-brand">SUPPLYMATE</span><h2>About SupplyMate</h2><p>A calm study desk for students working through pending papers, building a weekly plan, and preparing for their next exam.</p></section><nav className="landing-footer-links" aria-label="Quick Links"><h2>Quick Links</h2><a href="#top">Home</a><a href="#about">About SupplyMate</a><a href="#how-it-works">How It Works</a><button onClick={onAuth}>Log in / Register <ArrowUpRight size={14} /></button></nav><section className="landing-footer-team"><h2>
  Meet Our Team</h2><ol><li>Narendar</li><li>Nandhini</li><li>Ankitha</li><li>Akshay</li><li>Reshwanth</li></ol></section></div><div className="landing-footer-bottom"><span>Intermediate · Diploma · B.Tech</span><span>Copyright © 2026 SupplyMate. All rights reserved.</span></div></footer></div>; }
function Auth({ onLogin }: { onLogin: (student: Student) => void }) { const [mode, setMode] = useState<"login" | "register">("login"); const [error, setError] = useState(""); const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const email = String(data.get("email") || "").trim().toLowerCase(); const password = String(data.get("password") || ""); const students: Student[] = JSON.parse(localStorage.getItem("supplymate-students-v1") || "[]"); if (mode === "login") { const student = [...sampleStudents, ...students].find(s => s.email === email && s.password === password); if (!student) { setError("Use a sample account below or register a new student profile."); return; } onLogin(student); } else { const student: Student = { id: `student-${Date.now()}`, name: String(data.get("name") || "Student"), email, password, level: String(data.get("level") || "B.Tech") as Level }; localStorage.setItem("supplymate-students-v1", JSON.stringify([...students, student])); onLogin(student); } }; return <div className="auth-screen"><div className="auth-panel"><div className="auth-brand"><span className="brand-mark"><img src="/manus-storage/supplymate-logo_78424f77.png" alt="" /></span><b>SUPPLYMATE</b></div><p className="eyebrow">STUDENT ACCESS / {mode === "login" ? "LOG IN" : "REGISTER"}</p><h1>{mode === "login" ? "Let’s start with what you still need to clear." : "Make a study desk that is yours."}</h1><p className="auth-lede">{mode === "login" ? "Your saved papers and checkpoints are waiting here." : "You start at zero, then choose only the semesters and papers you actually need to clear."}</p><form onSubmit={submit}>{mode === "register" && <label>Student name<input name="name" required placeholder="Your full name" /></label>}<label>Email<input name="email" type="email" required placeholder="student@example.com" /></label><label>Password<input name="password" type="password" required placeholder="demo123" /></label>{mode === "register" && <label>Study level<select name="level" defaultValue="B.Tech"><option>Intermediate</option><option>Diploma</option><option>B.Tech</option></select></label>}{error && <p className="auth-error">{error}</p>}<Button className="primary-button" type="submit">{mode === "login" ? "Log in" : "Create profile"}<ArrowUpRight size={16} /></Button></form>{mode === "login" && <div className="sample-box"><p className="eyebrow">SAMPLE DESKS</p><p>All sample desks use password <b>demo123</b></p>{sampleStudents.map(s => <button key={s.id} onClick={() => onLogin(s)}><span>{s.name}</span><small>{s.email}</small></button>)}</div>}<button className="auth-switch" onClick={() => { setMode(mode === "login" ? "register" : "login"); setError(""); }}>{mode === "login" ? "New student? Register here" : "Already registered? Log in"}</button></div></div>; }
function Trail({ progress }: { progress: number }) { const done = Math.round(progress / 12.5); return <div className="trail"><span className="trail-line" style={{ width: `${Math.max(10, progress)}%` }} />{Array.from({ length: 8 }).map((_, i) => <i key={i} className={i < done ? "node done" : "node"} />)}</div>; }
function Header({ student, onNavigate, onLogout, onSwitch, previewMode }: { student: Student; onNavigate: (target: string) => void; onLogout: () => void; onSwitch: (student: Student) => void; previewMode: boolean }) { const [menuOpen, setMenuOpen] = useState(false); const [profileOpen, setProfileOpen] = useState(false); const initials = student.name.split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase(); const navigate = (target: string) => { setMenuOpen(false); onNavigate(target); }; return <header className="topbar"><div className="brand"><span className="brand-mark"><img src="/manus-storage/supplymate-logo_78424f77.png" alt="" /></span><span>SUPPLYMATE</span>{previewMode && <span className="demo-label">PREVIEW</span>}</div><nav className="main-nav"><button className="nav-link active" onClick={() => navigate("dashboard")}>Dashboard</button><button className="nav-link" onClick={() => navigate("syllabus")}>Syllabus</button><button className="nav-link" onClick={() => navigate("tests")}>Mock tests</button></nav><div className="top-actions"><div className="profile-wrap"><button className="profile profile-trigger" onClick={() => setProfileOpen(!profileOpen)}><span className="profile-initials">{initials}</span><b>{student.name}</b><ChevronRight size={14} className={profileOpen ? "profile-chevron open" : "profile-chevron"} /></button>{profileOpen && <div className="profile-menu"><p className="eyebrow">SIGNED IN AS</p><strong>{student.name}</strong><small>{student.email}</small><span className="profile-track">{student.level} student</span><div className="menu-divider" /><p className="eyebrow">SWITCH ACCOUNT</p>{sampleStudents.filter(item => item.id !== student.id).map(item => <button className="menu-item" key={item.id} onClick={() => { setProfileOpen(false); onSwitch(item); }}><span>{item.name}</span><small>{item.level}</small></button>)}<button className="menu-logout" onClick={onLogout}>Log out</button></div>}</div><button className="icon-button" aria-label="Open navigation menu" onClick={() => setMenuOpen(!menuOpen)}><Menu size={19} /></button></div>{menuOpen && <div className="nav-drawer"><div className="drawer-kicker">SUPPLYMATE / STUDY DESK</div><h2>What would you like to open?</h2><button onClick={() => navigate("dashboard")}>Dashboard <ArrowUpRight size={15} /></button><button onClick={() => navigate("syllabus")}>Syllabus <ArrowUpRight size={15} /></button><button onClick={() => navigate("tests")}>Mock tests <ArrowUpRight size={15} /></button><button onClick={() => navigate("syllabus")}>Download study pack <ArrowUpRight size={15} /></button></div>}</header>; }
function CurriculumPicker({ level, regulationId, setRegulationId, pathId, setPathId }: { level: Level; regulationId: string; setRegulationId: (id: string) => void; pathId: string; setPathId: (id: string) => void }) { const regulation = regulationCatalog[level].find(item => item.id === regulationId) || regulationCatalog[level][0]; return <section className="curriculum-picker"><div className="picker-header"><div><p className="eyebrow">CURRICULUM SETUP / STEP 1</p><h2>Choose your regulation, stream, or branch.</h2><p>Start with the framework your college or board follows, then choose the path and supply semesters.</p></div><span className="path-note">Exact subjects can vary by institution. Confirm the final subject list with your college.</span></div><div className="regulation-strip"><div><span className="eyebrow">REGULATION YEAR</span><strong>{regulation.label}</strong><small>{regulation.detail}</small>{regulation.source && <a href={regulation.source} target="_blank" rel="noreferrer">Open official source ↗</a>}</div><div className="regulation-tabs">{regulationCatalog[level].map(item => <button key={item.id} className={item.id === regulationId ? "selected" : ""} onClick={() => setRegulationId(item.id)}>{item.label}</button>)}</div></div><div className="curriculum-options">{curriculumCatalog[level].map(path => <button key={path.id} className={`curriculum-option ${path.id === pathId ? "selected" : ""}`} onClick={() => setPathId(path.id)}><span className="curriculum-radio">{path.id === pathId ? <Check size={14} /> : <span />}</span><span><b>{path.label}</b><small>{path.detail}</small><em>{path.subjects.length} subjects · {new Set(path.subjects.map(s => s.semester)).size} semesters mapped · {regulation.label}</em></span><ArrowUpRight size={16} /></button>)}</div></section>; }
function SubjectPicker({ level, availableSubjects, selectedCodes, selectedSemesters, setSelectedCodes }: { level: Level; availableSubjects: Subject[]; selectedCodes: string[]; selectedSemesters: number[]; setSelectedCodes: (next: string[]) => void }) { const toggle = (code: string) => setSelectedCodes(selectedCodes.includes(code) ? selectedCodes.filter(item => item !== code) : [...selectedCodes, code]); const grouped = selectedSemesters.map(semester => ({ semester, items: availableSubjects.filter(subject => subjectSem(level, subject) === semester) })).filter(group => group.items.length); return <section className="subject-picker"><div className="picker-header"><div><p className="eyebrow">SUPPLY SUBJECTS / STEP 2</p><h2>Which papers are still pending?</h2><p>Keep only the papers you need to clear. The dashboard, roadmap, and tests will follow this list.</p></div><div className="picker-actions"><span>{selectedCodes.length} selected</span><button onClick={() => setSelectedCodes(availableSubjects.map(s => s.code))}>Select all</button><button onClick={() => setSelectedCodes([])}>Clear all</button></div></div>{grouped.length ? <div className="subject-picker-groups">{grouped.map(group => <div className="subject-group" key={group.semester}><div className="subject-group-label"><span>SEM {group.semester}</span><small>{group.items.length} available</small></div><div className="subject-options">{group.items.map(subject => <button className={`subject-option ${selectedCodes.includes(subject.code) ? "selected" : ""}`} key={subject.code} onClick={() => toggle(subject.code)}><span className={`code-pill ${subject.color}`}>{subject.code}</span><span className="subject-option-copy"><b>{subject.name}</b><small>{subject.topics.length} roadmap topics · {subject.description}</small></span><span className="subject-option-check">{selectedCodes.includes(subject.code) ? <Check size={16} /> : <span />}</span></button>)}</div></div>)}</div> : <div className="picker-empty">Choose one or more semesters above to see the subjects available in each supply semester.</div>}</section>; }
function StudyResources({ level, regulationId, pathId }: { level: Level; regulationId: string; pathId: string }) { const resources = level === "Diploma" ? [{ title: "SBTET Telangana Diploma syllabus portal", detail: "Official branch and semester syllabus selector. Use this for the latest C-20/C-24 documents.", label: "Open official syllabus portal", url: "https://www.sbtet.telangana.gov.in/index.html#!/index/ViewSyllabus" }] : level === "B.Tech" ? [{ title: "JNTUH syllabus index", detail: "Official university index for regulation-wise B.Tech syllabus PDFs and updates.", label: "Open JNTUH syllabus index", url: "https://jntuh.ac.in/syllabus" }, ...(pathId === "btech-cse" ? [{ title: "JNTUH R22 B.Tech CSE syllabus PDF", detail: "Direct 154-page R22 course-structure and syllabus PDF with labs, electives, and project stages.", label: "Open R22 CSE PDF", url: "https://jntuh.ac.in/uploads/academics/R22B.Tech.CSECourseStructureSyllabus2.pdf" }] : [])] : [{ title: "JNTUH / SBTET reference portals", detail: "Choose the official syllabus source that matches your current board or college path.", label: "Open JNTUH syllabus index", url: "https://jntuh.ac.in/syllabus" }, { title: "SBTET Telangana Diploma portal", detail: "Use this when your subject belongs to a Polytechnic/Diploma path.", label: "Open SBTET portal", url: "https://www.sbtet.telangana.gov.in/index.html#!/index/ViewSyllabus" }]; return <section className="study-resources" id="resources"><div className="resource-heading"><div><p className="eyebrow">OFFICIAL STUDY PDFs / {regulationId.toUpperCase()}</p><h2>Official references for your track.</h2><p>Use these links to check the syllabus issued by your board or university. Subject codes can vary, so confirm the final list with your college.</p></div><span className="resource-stamp">PDF<br />SOURCE</span></div><div className="resource-grid">{resources.map(resource => <a className="resource-card" href={resource.url} target="_blank" rel="noreferrer" key={resource.url}><span className="pdf-badge">PDF</span><div><h3>{resource.title}</h3><p>{resource.detail}</p><b>{resource.label} ↗</b></div></a>)}</div></section>; }
const readImageAsDataUrl = (file: File) => new Promise<string>((resolve, reject) => {
  const reader = new FileReader();
  reader.onload = () => resolve(String(reader.result));
  reader.onerror = () => reject(new Error("The textbook photo could not be read."));
  reader.readAsDataURL(file);
});

function StudyHelper({ level, subjects }: { level: Level; subjects: Subject[] }) {
  const [messages, setMessages] = useState<Message[]>([]);
  const uploadImage = trpc.ai.uploadImage.useMutation();
  const chatMutation = trpc.ai.chat.useMutation({
    onSuccess: answer => setMessages(previous => [...previous, { role: "assistant", content: answer }]),
    onError: () => setMessages(previous => [...previous, { role: "assistant", content: "I couldn't reach the study helper just now. Please try again in a moment." }]),
  });
  const sendMessage = async (content: string, attachment?: File) => {
    const next = [...messages, { role: "user" as const, content, imageName: attachment?.name }];
    setMessages(next);
    try {
      const imageUrl = attachment ? (await uploadImage.mutateAsync({ dataUrl: await readImageAsDataUrl(attachment), fileName: attachment.name, mimeType: attachment.type as "image/jpeg" | "image/png" | "image/webp" })).url : undefined;
      chatMutation.mutate({
        messages: next.filter(message => message.role !== "system").map(({ role, content: text }) => ({ role: role as "user" | "assistant", content: text })),
        context: `${level} student; selected papers: ${subjects.length ? subjects.map(subject => subject.name).join(", ") : "none yet"}`,
        imageUrl,
      });
    } catch {
      setMessages(previous => [...previous, { role: "assistant", content: "I couldn't upload that textbook photo. Please use a JPG, PNG, or WEBP image under 5 MB and try again." }]);
    }
  };
  return <section className="study-helper-section" id="study-helper">
    <div className="study-helper-heading">
      <div><p className="eyebrow">ASK THE STUDY HELPER</p><h2>Stuck on a problem? Bring it here.</h2><p>Ask for a step-by-step explanation, a worked example, code help, or a quick revision plan. It can help with more than the papers on your desk.</p></div>
      <span className="helper-note"><Sparkles size={15} /> OpenAI-powered help</span>
    </div>
    <AIChatBox messages={messages} onSendMessage={sendMessage} isLoading={chatMutation.isPending || uploadImage.isPending} allowImageUpload height="440px" placeholder="Ask a question in your own words..." emptyStateMessage="Ask anything you are trying to understand." suggestedPrompts={["Explain this topic like I am new to it", "Solve this problem step by step", "Make me a quick revision plan"]} className="study-helper-box" />
    <p className="study-helper-disclaimer">AI can make mistakes. Check important formulas, code, and official syllabus details with your teacher or institution.</p>
  </section>;
}

function Dashboard({ level, setLevel, regulationId, setRegulationId, onExport, pathId, setPathId, subjects, availableSubjects, progress, openSubject, openTest, selectedSemesters, setSelectedSemesters, selectedCodes, setSelectedCodes }: { level: Level; setLevel: (l: Level) => void; regulationId: string; setRegulationId: (id: string) => void; onExport: () => void; pathId: string; setPathId: (id: string) => void; subjects: Subject[]; availableSubjects: Subject[]; progress: Record<string, boolean[]>; openSubject: (s: Subject) => void; openTest: () => void; selectedSemesters: number[]; setSelectedSemesters: (next: number[]) => void; selectedCodes: string[]; setSelectedCodes: (next: string[]) => void }) { const total = subjects.reduce((n, s) => n + s.topics.length, 0); const complete = subjects.reduce((n, s) => n + (progress[s.code] || []).filter(Boolean).length, 0); return <><section className="hero-banner"><div className="hero-copy"><p className="eyebrow">YOUR STUDY DESK / {level.toUpperCase()} TRACK</p><h1>Let’s get one<br /><em>paper moving.</em></h1><p className="hero-lede">Pick the semester, choose the paper, and keep this week’s work small enough to finish.</p><div className="hero-actions">{subjects[0] ? <Button className="primary-button" onClick={() => openSubject(subjects[0])}>Start {subjects[0].code} from Week 01 <ArrowUpRight size={16} /></Button> : <span className="hero-empty">Choose a semester below to put a paper on the desk.</span>}<a href="#syllabus" className="text-link">View full syllabus <ChevronRight size={15} /></a></div></div><div className="hero-note"><span className="note-label">ON THE DESK</span><strong>{subjects[0]?.topics[0]?.title || "Nothing picked yet"}</strong><span className="note-meta">{subjects[0]?.code || "Nothing picked yet"} · Week 01</span><div className="note-rule" /><span className="note-meta"><Target size={13} /> Every test starts at Question 1</span></div></section><section className="stats-row"><div><span>LEVEL TRACK</span><strong>{level === "B.Tech" ? "BTECH" : level.toUpperCase()}</strong></div><div><span>TOPICS COMPLETED</span><strong>{complete} <small>/ {total}</small></strong></div><div><span>SUBJECTS IN SYLLABUS</span><strong className="teal-text">{subjects.length}</strong></div><div className="stats-note"><TrendingUp size={16} /><span>Progress saved<br /><b>For this student track</b></span></div></section><section className="level-switcher"><div><p className="eyebrow">YOUR COURSE</p><h2>Start with the course you actually follow.</h2><p>Pick the level you are studying now. You can change it later without losing the rest of your desk.</p></div><div className="level-tabs">{(["Intermediate", "Diploma", "B.Tech"] as Level[]).map(item => <button className={item === level ? "selected" : ""} key={item} onClick={() => setLevel(item)}>{item}</button>)}</div></section><CurriculumPicker level={level} regulationId={regulationId} setRegulationId={setRegulationId} pathId={pathId} setPathId={setPathId} /><StudyResources level={level} regulationId={regulationId} pathId={pathId} /><section className="semester-picker"><div><p className="eyebrow">WHERE ARE THE PAPERS?</p><h2>Which semesters still have papers?</h2><p>Select every semester that has a supply paper. A new desk starts at zero completed topics.</p></div><div className="semester-tabs">{semesterOptions(level).map(semester => <button className={selectedSemesters.includes(semester) ? "selected" : ""} key={semester} onClick={() => setSelectedSemesters(selectedSemesters.includes(semester) ? selectedSemesters.filter(s => s !== semester) : [...selectedSemesters, semester])}>Sem {semester}</button>)}</div></section><SubjectPicker level={level} availableSubjects={availableSubjects} selectedCodes={selectedCodes} selectedSemesters={selectedSemesters} setSelectedCodes={setSelectedCodes} /><section className="section-block" id="syllabus"><div className="section-heading"><div><p className="eyebrow">PAPERS ON YOUR DESK / {level.toUpperCase()}</p><h2>The papers you picked.</h2></div><div className="section-actions"><button className="quiet-button" onClick={onExport}>Download study PDF <ArrowUpRight size={14} /></button><button className="quiet-button" onClick={openTest}>Start a mock test <ArrowUpRight size={14} /></button></div></div>{subjects.length ? <div className="subject-grid">{subjects.map(subject => { const pct = Math.round((progress[subject.code] || []).filter(Boolean).length / subject.topics.length * 100); return <button key={subject.code} className="subject-card" onClick={() => openSubject(subject)}><div className="card-top"><span className={`code-pill ${subject.color}`}>{subject.code}</span><ArrowUpRight className="card-arrow" size={17} /></div><h3>{subject.name}</h3><p>{subject.description}</p><Trail progress={pct} /><div className="progress-meta"><span>{(progress[subject.code] || []).filter(Boolean).length} of {subject.topics.length} topics complete</span><b>{pct}%</b></div><div className="progress-bar"><span style={{ width: `${pct}%` }} /></div><div className="card-bottom"><span>Latest readiness</span>{subject.pass ? <b className={subject.pass >= 65 ? "teal-text" : "amber-text"}>{subject.pass}%</b> : <b className="muted-text">Not tested</b>}</div></button>; })}</div> : <div className="empty-state"><h3>No papers on the desk yet.</h3><p>Choose one or more semesters above. The matching papers and tests will appear here.</p></div>}</section><section className="split-section" id="tests"><div className="insight-card"><div className="insight-art"><img src="/manus-storage/supplymate-study_07a90063.jpg" alt="Student studying" /></div><div className="insight-copy"><p className="eyebrow">A QUICK CHECK</p><h2>Try a short practice set.<br />See what needs another look.</h2><p>Answer a few questions without making a big event of it. Every new attempt starts from Question 1.</p><Button className="primary-button" onClick={openTest}>Open mock test <ArrowUpRight size={15} /></Button></div></div><div className="formula-card"><p className="eyebrow">WHAT IS INSIDE</p><h3>Intermediate.<br />Diploma. B.Tech.</h3><div className="formula-line"><b>04</b><span>Subjects per track</span></div><div className="formula-line"><b>08</b><span>Roadmap weeks each</span></div><div className="formula-line"><b>01</b><span>Fresh start per test</span></div><p className="formula-foot"><CircleHelp size={14} /> A practical starting list, not a college promise.</p></div></section><StudyHelper level={level} subjects={subjects} /></>; }
function SubjectView({ subject, level, progress, onProgress, onBack, onTest }: { subject: Subject; level: Level; progress: boolean[]; onProgress: (next: boolean[]) => void; onBack: () => void; onTest: () => void }) { const completed = progress.filter(Boolean).length; const pct = Math.round(completed / subject.topics.length * 100); return <><button className="back-button" onClick={onBack}><ArrowLeft size={15} /> {level} syllabus</button><section className="subject-head"><div><span className={`code-pill ${subject.color}`}>{subject.code}</span><h1>{subject.name}</h1><p>{subject.description}</p></div><div className="subject-score"><span>ROADMAP</span><strong>{pct}%</strong><small>{completed} of {subject.topics.length} topics</small></div></section><div className="subject-layout"><main><div className="roadmap-title"><div><p className="eyebrow">THE WEEK-BY-WEEK PLAN</p><h2>A week-by-week way through it.</h2></div><span>Saved here · {completed} / {subject.topics.length} complete</span></div><div className="roadmap-list">{subject.topics.map((item, i) => <div className="roadmap-item" key={item.week}><div className="week-rail"><span>W{String(item.week).padStart(2, "0")}</span><i className={progress[i] ? "big-node done" : "big-node"} /></div><div className={`roadmap-panel ${progress[i] ? "is-done" : ""}`}><div><h3>{item.title}</h3><p>{item.note}</p><div className="topic-resource"><span className="resource-type">{item.resource?.toLowerCase().includes(".pdf") ? "PDF" : "STUDY LINK"}</span>{item.resource ? <a href={item.resource} target="_blank" rel="noreferrer">{item.resourceLabel || "Open study material"} ↗</a> : <span className="resource-unavailable">A study link will be added here soon</span>}</div></div><button className="check-button" onClick={() => onProgress(progress.map((v, idx) => idx === i ? !v : v))}>{progress[i] ? <Check size={16} /> : <span />}</button></div></div>)}</div></main><aside className="checkpoint-panel"><div className="panel-top"><div><p className="eyebrow">MOCK TESTS / {subject.code}</p><h2>Use the checkpoint to see what sticks.</h2></div><MoreHorizontal size={18} /></div>{[1, 2, 3, 4].map(week => <button key={week} className={`checkpoint ${week === 1 ? "current" : ""}`} onClick={week === 1 ? onTest : undefined}><span className="checkpoint-week">W{String(week).padStart(2, "0")}</span><span><b>Week {week} checkpoint</b><small>10 questions · fresh start</small></span><ChevronRight size={16} /></button>)}<div className="panel-divider" /><p className="eyebrow">TRACK SUMMARY</p><div className="attempt"><span>Student track</span><b>{level}</b></div><div className="attempt"><span>Completed topics</span><b>{completed}</b></div></aside></div></>; }
function TestView({ subject, onBack, onResult }: { subject: Subject; onBack: () => void; onResult: (score: number) => void }) { const [selected, setSelected] = useState<Record<number, string>>({}); const questions = ["Which study action best supports this subject?", "What should you do after learning a new topic?", "What is the strongest revision signal?"]; const options = [["Skip the examples", "Work through a small example", "Avoid practice", "Only read the title"], ["Close the notes forever", "Explain it and solve one question", "Skip the checkpoint", "Wait until exam day"], ["A completed roadmap topic and a checked practice question", "A blank notebook", "No attempt", "Skipping the mock"]]; return <><button className="back-button" onClick={onBack}><ArrowLeft size={15} /> Back to roadmap</button><section className="test-heading"><div><p className="eyebrow">FRESH TEST SESSION / {subject.code}</p><h1>Week 01 checkpoint</h1><p>New attempt, Question 1. Choose the best answer for each question.</p></div><div className="question-count"><strong>01</strong><span>starts here</span></div></section><div className="quiz-wrap">{questions.map((q, qi) => <fieldset className="question-block" key={q}><legend><span>0{qi + 1}</span>{q}</legend>{options[qi].map((option, oi) => <label className={selected[qi] === String.fromCharCode(97 + oi) ? "option selected" : "option"} key={option}><input type="radio" name={`q${qi}`} onChange={() => setSelected({ ...selected, [qi]: String.fromCharCode(97 + oi) })} /><b>{String.fromCharCode(65 + oi)}</b><span>{option}</span></label>)}</fieldset>)}<Button className="primary-button submit-button" onClick={() => onResult(76)}>Submit checkpoint <ArrowUpRight size={16} /></Button></div></>; }
function SubjectTestView({ subject, onBack, onResult }: { subject: Subject; onBack: () => void; onResult: (score: number) => void }) { const [selected, setSelected] = useState<Record<number, number>>({}); const [submitted, setSubmitted] = useState(false); const questions = questionsForSubject(subject); const submit = () => { const correct = questions.reduce((total, question, index) => total + (selected[index] === question.answer ? 1 : 0), 0); setSubmitted(true); window.setTimeout(() => onResult(Math.round(correct / questions.length * 100)), 450); }; return <><button className="back-button" onClick={onBack}><ArrowLeft size={15} /> Back to roadmap</button><section className="test-heading"><div><p className="eyebrow">FRESH TEST SESSION / {subject.code}</p><h1>{subject.name} checkpoint</h1><p>Subject-specific questions. Every new attempt starts at Question 1.</p></div><div className="question-count"><strong>01</strong><span>{questions.length} questions</span></div></section><div className="quiz-wrap">{questions.map((question, qi) => <fieldset className={`question-block ${submitted ? "reviewed" : ""}`} key={question.prompt}><legend><span>{String(qi + 1).padStart(2, "0")}</span>{question.prompt}</legend>{question.options.map((option, oi) => { const chosen = selected[qi] === oi; const correct = question.answer === oi; return <label className={`option ${chosen ? "selected" : ""} ${submitted && correct ? "correct" : ""} ${submitted && chosen && !correct ? "incorrect" : ""}`} key={option}><input type="radio" name={`q${qi}`} checked={chosen} disabled={submitted} onChange={() => setSelected({ ...selected, [qi]: oi })} /><b>{String.fromCharCode(65 + oi)}</b><span>{option}</span></label>; })}{submitted && <p className="question-explanation"><Check size={14} /> {question.explanation}</p>}</fieldset>)}<Button className="primary-button submit-button" disabled={submitted || Object.keys(selected).length < questions.length} onClick={submit}>{submitted ? "Scoring attempt…" : `Submit ${subject.code} checkpoint`} <ArrowUpRight size={16} /></Button></div></>; }
function PrintStudySheet({ studentName, level, subjects, progress }: { studentName: string; level: Level; subjects: Subject[]; progress: Record<string, boolean[]> }) { return <div className="print-sheet"><header><div className="print-brand">SUPPLYMATE</div><div className="print-meta">OFFLINE STUDY PACK · {level.toUpperCase()}</div></header><h1>{studentName}'s supply study pack</h1><p className="print-intro">Selected supply subjects, roadmap checkpoints, resource links, and fresh mock questions. Use your browser's Print dialog and choose “Save as PDF”.</p>{subjects.length ? subjects.map(subject => { const questions = questionsForSubject(subject); const done = (progress[subject.code] || []).filter(Boolean).length; return <article className="print-subject" key={subject.code}><div className="print-subject-head"><span>{subject.code}</span><h2>{subject.name}</h2><small>{done} / {subject.topics.length} roadmap topics complete</small></div><p>{subject.description}</p><h3>Roadmap and resources</h3><ol>{subject.topics.map(topic => <li key={topic.week}><b>Week {String(topic.week).padStart(2, "0")} · {topic.title}</b><span>{topic.note}</span><a href={topic.resource}>{topic.resourceLabel}: {topic.resource}</a></li>)}</ol><h3>Mock questions</h3><ol className="print-questions">{questions.map(question => <li key={question.prompt}><b>{question.prompt}</b><span>{question.options.map((option, index) => `${String.fromCharCode(65 + index)}. ${option}`).join("   ")}</span></li>)}</ol></article>; }) : <div className="print-empty">Nothing picked yet yet. Return to the dashboard, choose your semesters and subjects, then export again.</div>}<footer>SUPPLYMATE · Start from Question 1 · Confirm official curriculum details with your institution.</footer></div>; }
function ResultView({ score, progressPct, onBack }: { score: number; progressPct: number; onBack: () => void }) { return <div className="result-view"><div className="result-card"><div className="result-icon"><Check size={23} /></div><p className="eyebrow">CHECKPOINT COMPLETE</p><h1>Your readiness signal</h1><div className="big-score"><strong>{score}%</strong><span>predicted pass percentage</span></div><div className="readiness-pill"><Sparkles size={14} /> High chance of clearing</div><div className="result-facts"><div><span>TEST SCORE</span><b>3 / 3 <small>(100%)</small></b></div><div><span>ROADMAP COMPLETE</span><b>{progressPct}%</b></div><div><span>SCORING MODEL</span><b>40 / 30 / 30</b></div></div><p className="result-note">This test began at Question 1. Your completed syllabus topics remain saved separately so your next attempt can start clean without losing study progress.</p><Button className="primary-button" onClick={onBack}>Continue the trail <ArrowUpRight size={16} /></Button></div></div>; }
export default function App() { const { data: authUser } = trpc.auth.me.useQuery(); const remoteStateQuery = trpc.student.state.useQuery(undefined, { enabled: Boolean(authUser) }); const saveRemoteState = trpc.student.saveState.useMutation(); const remoteHydrated = useRef(false); const forceLanding = new URLSearchParams(window.location.search).get("landing") === "1"; const [showLanding, setShowLanding] = useState(() => forceLanding || !localStorage.getItem("supplymate-current-student")); const [previewMode, setPreviewMode] = useState(() => !localStorage.getItem("supplymate-current-student")); const [student, setStudent] = useState<Student | null>(() => { if (forceLanding) return null; try { const id = localStorage.getItem("supplymate-current-student"); return id ? [...sampleStudents, ...JSON.parse(localStorage.getItem("supplymate-students-v1") || "[]")].find(s => s.id === id) || null : null; } catch { return null; } }); // Review-only query states keep the normal dashboard flow unchanged while allowing targeted preview checks.
 const qaMode = new URLSearchParams(window.location.search).get("qa"); const [view, setView] = useState<"dashboard" | "subject" | "test" | "result">(qaMode === "subject" || qaMode === "test" || qaMode === "result" ? qaMode : "dashboard"); const [level, setLevel] = useState<Level>(() => (localStorage.getItem("supplymate-level") as Level) || "B.Tech"); const [subject, setSubject] = useState<Subject>(curriculumCatalog["B.Tech"][0].subjects[0]); const [result, setResult] = useState(76); const [allProgress, setAllProgress] = useState<Record<Level, Record<string, boolean[]>>>(() => JSON.parse(JSON.stringify(starterProgress))); const [semesterSelections, setSemesterSelections] = useState<Record<Level, number[]>>({ Intermediate: [], Diploma: [], "B.Tech": [] }); const [selectedSubjects, setSelectedSubjects] = useState<Record<Level, string[]>>({ Intermediate: [], Diploma: [], "B.Tech": [] }); const [pathSelections, setPathSelections] = useState<Record<Level, string>>({ Intermediate: "mpc", Diploma: "diploma-cse", "B.Tech": "btech-cse" }); const [regulationSelections, setRegulationSelections] = useState<Record<Level, string>>({ Intermediate: "ts-intermediate-general", Diploma: "sbtet-c20", "B.Tech": "jntuh-r22" }); const activePath = curriculumCatalog[level].find(path => path.id === pathSelections[level]) || curriculumCatalog[level][0]; const availableSubjects = useMemo(() => activePath.subjects.filter(s => semesterSelections[level].includes(subjectSem(level, s))), [activePath, level, semesterSelections]); const subjects = useMemo(() => availableSubjects.filter(s => selectedSubjects[level].includes(s.code)), [availableSubjects, level, selectedSubjects]); const progress = allProgress[level]; useEffect(() => { if (authUser && remoteStateQuery.data && !remoteHydrated.current) { const remote = remoteStateQuery.data as Partial<{ progress: Record<Level, Record<string, boolean[]>>; semesters: Record<Level, number[]>; subjects: Record<Level, string[]>; paths: Record<Level, string>; regulations: Record<Level, string> }>; if (remote.progress) setAllProgress(remote.progress as Record<Level, Record<string, boolean[]>>); if (remote.semesters) setSemesterSelections(remote.semesters); if (remote.subjects) setSelectedSubjects(remote.subjects); if (remote.paths) setPathSelections(remote.paths); if (remote.regulations) setRegulationSelections(remote.regulations); remoteHydrated.current = true; } }, [authUser, remoteStateQuery.data]); useEffect(() => { if (!student) return; const saved = JSON.parse(localStorage.getItem(`supplymate-state-${student.id}`) || "null"); if (saved) { setAllProgress(saved.progress || JSON.parse(JSON.stringify(starterProgress))); setSemesterSelections(saved.semesters || { Intermediate: [], Diploma: [], "B.Tech": [] }); setSelectedSubjects(saved.subjects || { Intermediate: [], Diploma: [], "B.Tech": [] }); setPathSelections(saved.paths || { Intermediate: "mpc", Diploma: "diploma-cse", "B.Tech": "btech-cse" }); setRegulationSelections(saved.regulations || { Intermediate: "ts-intermediate-general", Diploma: "sbtet-c20", "B.Tech": "jntuh-r22" }); } else { setAllProgress(JSON.parse(JSON.stringify(starterProgress))); setSemesterSelections({ Intermediate: [], Diploma: [], "B.Tech": [] }); setSelectedSubjects({ Intermediate: [], Diploma: [], "B.Tech": [] }); setPathSelections({ Intermediate: "mpc", Diploma: "diploma-cse", "B.Tech": "btech-cse" }); setRegulationSelections({ Intermediate: "ts-intermediate-general", Diploma: "sbtet-c20", "B.Tech": "jntuh-r22" }); } setLevel(student.level); }, [student]); useEffect(() => { if (student) { const state = { progress: allProgress, semesters: semesterSelections, subjects: selectedSubjects, paths: pathSelections, regulations: regulationSelections }; localStorage.setItem(`supplymate-state-${student.id}`, JSON.stringify(state)); localStorage.setItem("supplymate-current-student", student.id); if (authUser && remoteHydrated.current) { const timer = window.setTimeout(() => saveRemoteState.mutate(state), 250); return () => window.clearTimeout(timer); } } }, [student, allProgress, semesterSelections, selectedSubjects, pathSelections, regulationSelections, authUser]); useEffect(() => { setSubject(activePath.subjects[0]); }, [level, activePath]); const openSubject = (s: Subject) => { setSubject(s); setView("subject"); window.scrollTo({ top: 0, behavior: "smooth" }); }; const openTest = () => { if (!subjects[0]) return; setSubject(subjects[0]); setView("test"); window.scrollTo({ top: 0, behavior: "smooth" }); }; const updateProgress = (next: boolean[]) => setAllProgress({ ...allProgress, [level]: { ...progress, [subject.code]: next } }); const content = view === "dashboard" ? <Dashboard level={level} setLevel={setLevel} regulationId={regulationSelections[level]} onExport={() => downloadStudyPdf(student?.name || "Student", level, subjects, progress)} setRegulationId={id => { setRegulationSelections({ ...regulationSelections, [level]: id }); setPathSelections({ ...pathSelections, [level]: curriculumCatalog[level][0].id }); setSemesterSelections({ ...semesterSelections, [level]: [] }); setSelectedSubjects({ ...selectedSubjects, [level]: [] }); }} pathId={activePath.id} setPathId={id => { setPathSelections({ ...pathSelections, [level]: id }); setSemesterSelections({ ...semesterSelections, [level]: [] }); setSelectedSubjects({ ...selectedSubjects, [level]: [] }); }} subjects={subjects} availableSubjects={availableSubjects} progress={progress} openSubject={openSubject} openTest={openTest} selectedSemesters={semesterSelections[level]} setSelectedSemesters={next => { const nextAvailable = activePath.subjects.filter(s => next.includes(subjectSem(level, s))); setSemesterSelections({ ...semesterSelections, [level]: next }); setSelectedSubjects({ ...selectedSubjects, [level]: selectedSubjects[level].filter(code => nextAvailable.some(s => s.code === code)) }); }} selectedCodes={selectedSubjects[level]} setSelectedCodes={next => setSelectedSubjects({ ...selectedSubjects, [level]: next })} /> : view === "subject" ? <SubjectView subject={subject} level={level} progress={progress[subject.code] || Array(8).fill(false)} onProgress={updateProgress} onBack={() => setView("dashboard")} onTest={openTest} /> : view === "test" ? <SubjectTestView subject={subject} onBack={() => setView("subject")} onResult={score => { setResult(score); setView("result"); }} /> : <ResultView score={result} progressPct={Math.round((progress[subject.code] || []).filter(Boolean).length / subject.topics.length * 100)} onBack={() => setView("subject")} />; if (!student) return showLanding ? <Landing onDemo={() => { setPreviewMode(true); setShowLanding(false); setStudent(sampleStudents[0]); }} onAuth={() => setShowLanding(false)} /> : <Auth onLogin={next => { setPreviewMode(false); setShowLanding(false); setStudent(next); setLevel(next.level); setView("dashboard"); }} />; return <div className="site-shell"><Header previewMode={previewMode} student={student} onNavigate={target => { setView("dashboard"); window.setTimeout(() => { if (target === "dashboard") window.scrollTo({ top: 0, behavior: "smooth" }); else document.getElementById(target)?.scrollIntoView({ behavior: "smooth" }); }, 0); }} onLogout={() => { localStorage.removeItem("supplymate-current-student"); setPreviewMode(false); setShowLanding(true); setStudent(null); setView("dashboard"); }} onSwitch={next => { setPreviewMode(false); setStudent(next); setLevel(next.level); setView("dashboard"); window.scrollTo({ top: 0 }); }} /><main className="page-shell">{content}</main><PrintStudySheet studentName={student.name} level={level} subjects={subjects} progress={progress} /><footer className="footer"><span className="brand-mark small-mark"><img src="/manus-storage/supplymate-logo_78424f77.png" alt="" /></span><b>SUPPLYMATE</b><span>Plan your supplies and study at your own pace.</span><span className="footer-right">Built for Intermediate · Diploma · B.Tech</span></footer></div>; }
